```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Glowing Rainbow Text</title>
  <style>
    body {
      background: #111;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0;
    }
    .rainbow-glow {
      font-size: 3rem;
      font-weight: bold;
      color: #fff;
      padding: 1em 2em;
      border: 6px solid;
      border-radius: 16px;
      text-align: center;
      background: #111;
      text-shadow:
        0 0 10px #fff,
        0 0 20px #fff,
        0 0 30px #ff00de,
        0 0 40px #ff00de;
      border-image: conic-gradient(
        from 0deg,
        red, orange, yellow, green, blue, indigo, violet, red
      ) 1;
      animation: spin 4s linear infinite;
