**src/main.rs:**
```rust
use eframe::{egui, epi};
use notify::{RecommendedWatcher, RecursiveMode, Watcher, Event};
use rfd::FileDialog;
use crossbeam_channel::{unbounded, Receiver};
use std::thread;
use std::path::PathBuf;

struct AppState {
    input_dir: Option<PathBuf>,
    output_dir: Option<PathBuf>,
    done_dir: Option<PathBuf>,
    logs: Vec<String>,
    watching: bool,
    event_rx: Option<Receiver<Event>>,
    watcher_thread: Option<thread::JoinHandle<()>>,
}

impl Default for AppState {
    fn default() -> Self {
        Self {
            input_dir: None,
            output_dir: None,
            done_dir: None,
            logs: vec![],
            watching: false,
            event_rx: None,
            watcher_thread: None,
        }
    }
}

impl epi::App for AppState {
    fn name(&self) -> &str {
        "Rust Folder Monitor"
    }

    fn update(&mut self, ctx: &egui::Context, _frame: &epi::Frame) {
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            ui.horizontal(|ui| {
                if ui.button("Select Input Folder").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        self.input_dir = Some(path);
                    }
                }
                ui.label(self.input_dir.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string()));
            });

            ui.horizontal(|ui| {
                if ui.button("Select Output Folder").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        self.output_dir = Some(path);
                    }
                }
                ui.label(self.output_dir.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string()));
            });

            ui.horizontal(|ui| {
                if ui.button("Select Done Folder").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        self.done_dir = Some(path);
                    }
                }
                ui.label(self.done_dir.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string()));
            });

            ui.add_space(10.0);

            if !self.watching {
                if ui.button("Start").clicked() {
                    if let Some(input_path) = &self.input_dir {
                        let (tx, rx) = unbounded();
                        let watch_path = input_path.clone();
                        let watcher_thread = thread::spawn(move || {
                            let mut watcher = RecommendedWatcher::new(
                                move |res| {
                                    if let Ok(event) = res {
                                        let _ = tx.send(event);
                                    }
                                }
                            ).expect("Failed to create watcher");
                            watcher.watch(&watch_path, RecursiveMode::NonRecursive).expect("Failed to watch directory");
                            loop { std::thread::sleep(std::time::Duration::from_secs(60)); }
                        });
                        self.event_rx = Some(rx);
                        self.watcher_thread = Some(watcher_thread);
                        self.watching = true;
                        self.logs.push(format!("Started watching: {}", input_path.display()));
                    } else {
                        self.logs.push("Please select an input folder first.".to_string());
                    }
                }
            }

            ui.separator();
            ui.label("Events:");
            egui::ScrollArea::vertical().max_height(200.0).show(ui, |ui| {
                for log in &self.logs {
                    ui.label(log);
                }
            });
        });

        if let Some(rx) = &self.event_rx {
            while let Ok(event) = rx.try_recv() {
                let desc = format!("Event: {:?} | Paths: {:?}", event.kind, event.paths);
                self.logs.push(desc);
                ctx.request_repaint();
            }
        }
    }
}

fn main() {
    let app = AppState::default();
    let native_options = eframe::NativeOptions::default();
    eframe::run_native(Box::new(app), native_options);
}
```

