#include <fstream>
#include <iostream>
#include <unistd.h> // for sleep()

int main() {
    // Export GPIO pins
    std::ofstream export_file("/sys/class/gpio/export");
    export_file << "17"; export_file.close();
    export_file.open("/sys/class/gpio/export"); export_file << "18"; export_file.close();
    export_file.open("/sys/class/gpio/export"); export_file << "22"; export_file.close();
    export_file.open("/sys/class/gpio/export"); export_file << "23"; export_file.close();

    // Wait for sysfs to create the gpio folders
    sleep(1);

    // Set GPIO directions to output
    std::ofstream dir_file("/sys/class/gpio/gpio17/direction");
    dir_file << "out"; dir_file.close();
    dir_file.open("/sys/class/gpio/gpio18/direction"); dir_file << "out"; dir_file.close();
    dir_file.open("/sys/class/gpio/gpio22/direction"); dir_file << "out"; dir_file.close();
    dir_file.open("/sys/class/gpio/gpio23/direction"); dir_file << "out"; dir_file.close();

    // Set motor directions
    // Motor 1: IN1=1, IN2=0 (forward)
    std::ofstream val_file("/sys/class/gpio/gpio17/value");
    val_file << "1"; val_file.close();
    val_file.open("/sys/class/gpio/gpio18/value"); val_file << "0"; val_file.close();

    // Motor 2: IN3=0, IN4=1 (reverse)
    val_file.open("/sys/class/gpio/gpio22/value"); val_file << "0"; val_file.close();
    val_file.open("/sys/class/gpio/gpio23/value"); val_file << "1"; val_file.close();

    // Let motors run for 5 seconds
    sleep(5);

    // Stop both motors (set all IN pins to 0)
    val_file.open("/sys/class/gpio/gpio17/value"); val_file << "0"; val_file.close();
    val_file.open("/sys/class/gpio/gpio18/value"); val_file << "0"; val_file.close();
    val_file.open("/sys/class/gpio/gpio22/value"); val_file << "0"; val_file.close();
    val_file.open("/sys/class/gpio/gpio23/value"); val_file << "0"; val_file.close();

    return 0;
}
