### Step 2: Prepare Flake Directory

We'll use `/etc/nixos` for the flake.

```sh
cd /etc/nixos
sudo mv configuration.nix configuration.nix.bak  # backup old config
sudo rm hardware-configuration.nix  # we'll import it in the flake
sudo mkdir flake
cd flake
sudo git init  # optional, for version control
```

Copy your `/etc/nixos/hardware-configuration.nix` into `/etc/nixos/flake/`.

---

### Step 3: Create `flake.nix`

Create `/etc/nixos/flake/flake.nix`:

```nix
{
  description = "NixOS config with flakes and Home Manager";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager.url = "github:nix-community/home-manager";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, home-manager, flake-utils, ... }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
        username = "alice";  # change to your user
        hostname = "nixos";  # change to your hostname
      in {
        nixosConfigurations.${hostname} = nixpkgs.lib.nixosSystem {
          system = system;
          modules = [
            ./hardware-configuration.nix
            ({ config, pkgs, ... }: {
              networking.hostName = hostname;
              time.timeZone = "UTC";
              i18n.defaultLocale = "en_US.UTF-8";
              users.users.${username} = {
                isNormalUser = true;
                extraGroups = [ "wheel" "networkmanager" ];
                shell = pkgs.zsh;
              };
              services.xserver.enable = true;
              services.xserver.displayManager.gdm.enable = true;
              services.xserver.displayManager.gdm.wayland = true;
              services.xserver.desktopManager.gnome.enable = true;
              services.xserver.desktopManager.gnome.wayland = true;
              services.xserver.layout = "us";
              services.networkmanager.enable = true;
              environment.systemPackages = with pkgs; [
                curl git htop wget unzip tree tmux gcc make python3
                neovim
                vscode
                brave
                bitwarden
                # Zed may not be in nixpkgs; see below
              ];
              programs.zsh.enable = true;
              security.sudo.wheelNeedsPassword = false;
              system.stateVersion = "23.11"; # adjust to your version
              # Home Manager integration
              home-manager = {
                useGlobalPkgs = true;
                useUserPackages = true;
                users.${username} = import ./home.nix;
              };
            })
          ];
        };
      }
    );
}
```

---

### Step 4: Create `home.nix` for Home Manager

Create `/etc/nixos/flake/home.nix`:

```nix
{ config, pkgs, ... }:

{
  home.username = "alice";  # change to your user
