  return new Promise((resolve, reject) => {
    bcrypt.compare(plain, hash, (err, result) => {
      if (err) return reject(err);
      resolve(result);
    });
  });
}

// パスワードバリデーション
function validateNewPasswords(
  current: string,
  next: string,
  confirm: string
): string | null {
  if (current === next) {
    return "新しいパスワードは現在のパスワードと違うものを入力してください";
  }
  if (next !== confirm) {
    return "新しいパスワードが一致しません";
  }
  return null;
}

