      const chars = editor.value.length;
      status.textContent = `Lines: ${lines} | Words: ${words} | Chars: ${chars}`;
    }
    function escapeHtml(str) {
      return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    function syntaxHighlight(text, lang) {
      text = escapeHtml(text);
      if(lang === 'plaintext') return text;
      if(lang === 'javascript') {
        text = text.replace(/(\/\/.*|\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        text = text.replace(/(["'`])(?:\\.|(?!\1).)*\1/g, '<span class="token string">$&</span>');
