        text = text.replace(/\b\d+\.?\d*(e[+-]?\d+)?\b/gi, '<span class="token number">$&</span>');
      } else if(lang === 'html') {
        text = text.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="token comment">$1</span>');
        text = text.replace(/(&lt;\/?[a-zA-Z]+)([^&]*?)(&gt;)/g, function(_, p1, p2, p3) {
          p2 = p2.replace(/([a-zA-Z-:]+)(=)("[^"]*"|'[^']*')/g, '<span class="token attr">$1</span>$2<span class="token attr-value">$3</span>');
          return '<span class="token tag">'+p1+'</span>' + p2 + '<span class="token tag">'+p3+'</span>';
        });
      } else if(lang === 'css') {
        text = text.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        text = text.replace(/([.#]?[a-zA-Z0-9_-]+)(\s*\{)/g, '<span class="token selector">$1</span>$2');
        text = text.replace(/([a-zA-Z-]+)(:)/g, '<span class="token property">$1</span>$2');
        text = text.replace(/(["'])(?:\\.|(?!\1).)*\1/g, '<span class="token string">$&</span>');
        text = text.replace(/\b\d+(\.\d+)?(px|em|rem|%)?\b/g, '<span class="token number">$&</span>');
      }
      return text;
    }
    function updateHighlighting() {
      highlighting.innerHTML = syntaxHighlight(editor.value, language);
    }
    function updateAll() {
      updateLineNumbers();
      updateStatus();
      updateHighlighting();
