#include <QCoreApplication>
#include <QDebug>
#include <QSet>
#include <QRegularExpression>
#include "xlsxdocument.h"

using namespace QXlsx;

bool parseNumber(const QVariant &cellValue, int &result) {
    // If it's a number, check if it's an integer
    if (cellValue.canConvert<double>()) {
        double d = cellValue.toDouble();
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d + 1.0, i + 1.0)) {
            result = i;
            return true;
        }
    }
    // If it's a string, parse possible formats
    QString s = cellValue.toString().trimmed().toLower();
    if (s.isEmpty()) return false;

    // Binary: 0b101010 or b101010
    QRegularExpression reBin("^(0b|b)([01]+)$");
    auto mBin = reBin.match(s);
    if (mBin.hasMatch()) {
        result = mBin.captured(2).toInt(nullptr, 2);
        return true;
    }
    // Hex: 0x2a or 2ah
    QRegularExpression reHex1("^0x([0-9a-f]+)$");
    QRegularExpression reHex2("^([0-9a-f]+)h$");
    auto mHex1 = reHex1.match(s);
    auto mHex2 = reHex2.match(s);
    if (mHex1.hasMatch()) {
        result = mHex1.captured(1).toInt(nullptr, 16);
        return true;
    }
    if (mHex2.hasMatch()) {
        result = mHex2.captured(1).toInt(nullptr, 16);
        return true;
    }
    // Octal: 0o52 or 052
    QRegularExpression reOct("^0o([0-7]+)$");
    auto mOct = reOct.match(s);
    if (mOct.hasMatch()) {
        result = mOct.captured(1).toInt(nullptr, 8);
        return true;
    }
    if (s.startsWith('0') && s.length() > 1 && s.indexOf(QRegularExpression("[^0-7]")) == -1) {
        result = s.toInt(nullptr, 8);
        return true;
    }
    // Decimal integer
    bool ok = false;
    int val = s.toInt(&ok, 10);
    if (ok) {
        result = val;
        return true;
    }
    // Decimal float, but only if it's an integer
    double d = s.toDouble(&ok);
    if (ok) {
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d + 1.0, i + 1.0)) {
            result = i;
            return true;
        }
    }
    return false;
}

int main(int argc, char *argv[]) {
    QCoreApplication a(argc, argv);
    QString filePath = "file.xlsx";
    QString cellRef = "A1";
    Document xlsx(filePath);
    if (!xlsx.load()) {
        qWarning() << "Failed to load file";
        return -1;
    }
    QVariant cellValue = xlsx.read(cellRef);
    if (!cellValue.isValid()) {
        qWarning() << "Invalid cell";
        return -1;
    }
    int number;
    if (!parseNumber(cellValue, number)) {
        qWarning() << "Could not parse cell value";
        return -1;
    }
    QSet<int> allowed = {0, 1, 2, 3, 10, 11, 42};
    if (allowed.contains(number)) {
        qDebug() << "Cell contains allowed value:" << number;
    } else {
        qDebug() << "Cell contains NOT allowed value:" << number;
    }
    return 0;
}
