    }
    .file-list li {
      padding: 4px 0;
      cursor: pointer;
      border-bottom: 1px solid #ccc;
    }
    .file-list li:last-child {
      border-bottom: none;
    }
    textarea {
      width: 100%; height: 90%;
      resize: none;
      font-family: monospace;
    }
  </style>
</head>
<body>
  <div id="desktop">
    <div class="icon" style="top:20px;left:20px;" onclick="openApp('explorer')">
      <img src="https://via.placeholder.com/48?text=📁" alt="File Explorer">
      <div>File Explorer</div>
    </div>
    <div class="icon" style="top:110px;left:20px;" onclick="openApp('notepad')">
      <img src="https://via.placeholder.com/48?text=📝" alt="Notepad">
      <div>Notepad</div>
    </div>
  </div>
  <div id="taskbar"></div>
  <script>
    let zIndex = 10;
    let files = [
      {name: "readme.txt", content: "Welcome to the OS Emulator!"},
      {name: "todo.txt", content: "1. Try File Explorer\n2. Try Notepad"}
    ];

    function openApp(app, fileIdx) {
      if (app === 'explorer') {
        createWindow('File Explorer', buildExplorer());
      } else if (app === 'notepad') {
        createWindow('Notepad', buildNotepad());
      } else if (app === 'editfile') {
        createWindow(files[fileIdx].name, buildNotepad(files[fileIdx], fileIdx));
      }
    }

    function buildExplorer() {
      let ul = document.createElement('ul');
      ul.className = 'file-list';
      files.forEach((f, i) => {
        let li = document.createElement('li');
        li.textContent = f.name;
        li.onclick = () => openApp('editfile', i);
        ul.appendChild(li);
      });
      return ul;
    }

    function buildNotepad(file, idx) {
      let ta = document.createElement('textarea');
      ta.value = file ? file.content : '';
      let saveBtn = document.createElement('button');
      saveBtn.textContent = 'Save';
      saveBtn.onclick = () => {
        if (file) {
          file.content = ta.value;
          alert('Saved!');
        } else {
          let name = prompt('File name?', 'untitled.txt');
          if (name) {
            files.push({name, content: ta.value});
            alert('Saved as ' + name);
          }
        }
      };
      let div = document.createElement('div');
      div.appendChild(ta);
      div.appendChild(document.createElement('br'));
      div.appendChild(saveBtn);
      return div;
    }

    function createWindow(title, content) {
      let win = document.createElement('div');
      win.className = 'window';
      win.style.top = (60 + Math.random()*100) + 'px';
      win.style.left = (120 + Math.random()*100) + 'px';
      win.style.zIndex = ++zIndex;

      let titlebar = document.createElement('div');
      titlebar.className = 'titlebar';
      titlebar.innerHTML = `<span>${title}</span><span class="close-btn">×</span>`;
      win.appendChild(titlebar);

      let cont = document.createElement('div');
      cont.className = 'content';
      cont.appendChild(content);
      win.appendChild(cont);

      document.body.appendChild(win);

      // Dragging
      let offsetX, offsetY, dragging = false;
      titlebar.onmousedown = function(e) {
        dragging = true;
        offsetX = e.clientX - win.offsetLeft;
        offsetY = e.clientY - win.offsetTop;
        document.onmousemove = function(e2) {
          if (dragging) {
            win.style.left = (e2.clientX - offsetX) + 'px';
            win.style.top = (e2.clientY - offsetY) + 'px';
            win.style.zIndex = ++zIndex;
          }
        };
        document.onmouseup = function() {
          dragging = false;
          document.onmousemove = null;
          document.onmouseup = null;
        };
      };

      // Close
      titlebar.querySelector('.close-btn').onclick = () => {
        win.remove();
      };
    }
  </script>
</body>
