  <div id="desktop"></div>
  <div id="taskbar"></div>
  <script>
    // In-memory file system
    let files = {
      "Readme.txt": "Welcome to the Simple OS Emulator!\nYou can create, edit, and delete files.",
      "Notes.txt": "This is a sample note."
    };

    // Window management
    let zCounter = 100;
    let windows = [];

    function createDesktopIcon(name, icon, app) {
      let div = document.createElement('div');
      div.className = 'desktop-icon';
      div.innerHTML = `<img src="${icon}" alt=""><div>${name}</div>`;
      div.onclick = () => openApp(app);
      return div;
    }

    function renderDesktop() {
      let desktop = document.getElementById('desktop');
      desktop.innerHTML = '';
      desktop.appendChild(createDesktopIcon('File Explorer', 'https://img.icons8.com/fluency/48/folder-invoices.png', 'explorer'));
      desktop.appendChild(createDesktopIcon('Text Editor', 'https://img.icons8.com/fluency/48/notepad.png', 'editor'));
    }

    function openApp(app, fileName) {
      if (app === 'explorer') {
        openWindow('File Explorer', createFileExplorer());
      } else if (app === 'editor') {
        openWindow('Text Editor', createTextEditor(fileName));
      }
    }

    function openWindow(title, content) {
      let win = document.createElement('div');
      win.className = 'window';
      win.style.top = (60 + Math.random()*100) + 'px';
      win.style.left = (120 + Math.random()*100) + 'px';
      win.style.zIndex = ++zCounter;

      let titlebar = document.createElement('div');
      titlebar.className = 'titlebar';
      titlebar.innerHTML = `<span>${title}</span>`;
      let controls = document.createElement('span');
      controls.className = 'controls';
      let closeBtn = document.createElement('button');
      closeBtn.innerHTML = '×';
      closeBtn.onclick = (e) => {
        e.stopPropagation();
        win.remove();
        removeTaskbarApp(win);
      };
      controls.appendChild(closeBtn);
      titlebar.appendChild(controls);
      win.appendChild(titlebar);

      let contentDiv = document.createElement('div');
      contentDiv.className = 'content';
      contentDiv.appendChild(content);
      win.appendChild(contentDiv);

      // Dragging
      let offsetX, offsetY, dragging = false;
      titlebar.onmousedown = function(e) {
        dragging = true;
        offsetX = e.clientX - win.offsetLeft;
        offsetY = e.clientY - win.offsetTop;
        win.style.zIndex = ++zCounter;
      };
      document.onmousemove = function(e) {
        if (dragging) {
          win.style.left = (e.clientX - offsetX) + 'px';
          win.style.top = (e.clientY - offsetY) + 'px';
        }
      };
      document.onmouseup = function() { dragging = false; };

      document.body.appendChild(win);
      addTaskbarApp(win, title);
      windows.push(win);
    }

    function addTaskbarApp(win, title) {
      let taskbar = document.getElementById('taskbar');
      let btn = document.createElement('div');
      btn.className = 'taskbar-app';
      btn.textContent = title;
      btn.onclick = () => {
        win.style.zIndex = ++zCounter;
      };
      win._taskbarBtn = btn;
      taskbar.appendChild(btn);
    }
    function removeTaskbarApp(win) {
      if (win._taskbarBtn) win._taskbarBtn.remove();
    }

    // File Explorer
    function createFileExplorer() {
      let div = document.createElement('div');
      let toolbar = document.createElement('div');
      toolbar.className = 'file-explorer-toolbar';
      let btnNew = document.createElement('button');
      btnNew.textContent = 'New File';
      btnNew.onclick = () => {
        let name = prompt('File name?');
        if (name && !files[name]) {
          files[name] = '';
          renderList();
        }
      };
      let btnDelete = document.createElement('button');
      btnDelete.textContent = 'Delete';
      btnDelete.disabled = true;
      let btnRename = document.createElement('button');
      btnRename.textContent = 'Rename';
      btnRename.disabled = true;
      toolbar.append(btnNew, btnDelete, btnRename);
      div.appendChild(toolbar);

      let list = document.createElement('div');
      list.className = 'file-list';
      div.appendChild(list);

      let selected = null;

      function renderList() {
        list.innerHTML = '';
        Object.keys(files).forEach(fname => {
          let fdiv = document.createElement('div');
          fdiv.textContent = fname;
          fdiv.onclick = () => {
            [...list.children].forEach(c => c.classList.remove('selected'));
            fdiv.classList.add('selected');
            selected = fname;
            btnDelete.disabled = false;
            btnRename.disabled = false;
          };
          fdiv.ondblclick = () => {
            openApp('editor', fname);
          };
          list.appendChild(fdiv);
        });
        btnDelete.disabled = true;
        btnRename.disabled = true;
        selected = null;
      }
      btnDelete.onclick = () => {
        if (selected && confirm('Delete ' + selected + '?')) {
          delete files[selected];
          renderList();
        }
      };
      btnRename.onclick = () => {
        if (selected) {
          let newName = prompt('Rename to:', selected);
          if (newName && !files[newName]) {
            files[newName] = files[selected];
            delete files[selected];
            renderList();
          }
        }
      };
      renderList();
      return div;
    }

    // Text Editor
    function createTextEditor(fname) {
      let div = document.createElement('div');
      div.className = 'text-editor';
      let textarea = document.createElement('textarea');
      textarea.value = fname && files[fname] !== undefined ? files[fname] : '';
      div.appendChild(textarea);
      let btnSave = document.createElement('button');
      btnSave.textContent = 'Save';
      btnSave.onclick = () => {
        let name = fname || prompt('Save as:', 'Untitled.txt');
        if (name) {
          files[name] = textarea.value;
          alert('Saved!');
        }
      };
      div.appendChild(btnSave);
      return div;
    }

    renderDesktop();
  </script>
</body>
</html>
```

