**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: some edges (roads) already exist, and the cost to build a new road between two houses is the sum of their prices. The goal is to ensure the city is fully connected at minimal cost.

**Approach:**

1. **Model the city as a graph:** Each house is a node. Existing roads are edges with zero cost (since they're already built).
2. **Find connected components:** Use Union-Find (DSU) to identify which houses are already connected.
3. **Connect components:** For each component, find the house with the minimal price. Then, connect all components together by always connecting their minimal-price house to the global minimal-price house among all components. This ensures minimal cost.
4. **Output:** The number of new roads and the pairs of houses to connect.

**Implementation (C++):**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n+1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n+1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    // Find the cheapest house in each component
    unordered_map<int, pair<long long, int>> comp_min;
    for (int i = 1; i <= n; ++i) {
        int p = dsu.find(i);
        if (comp_min.count(p) == 0 || a[i] < comp_min[p].first)
            comp_min[p] = {a[i], i};
    }

    // Find the global minimum
    int global_min = -1;
    long long min_price = LLONG_MAX;
    for (auto& [p, pr] : comp_min) {
        if (pr.first < min_price) {
            min_price = pr.first;
            global_min = pr.second;
        }
    }

    vector<pair<int, int>> new_roads;
    for (auto& [p, pr] : comp_min) {
        if (pr.second != global_min)
            new_roads.emplace_back(global_min, pr.second);
    }

    cout << new_roads.size() << "\n";
    for (auto& [u, v] : new_roads)
        cout << u << " " << v << "\n";
    return 0;
}
```

**Explanation:**
