This is a classic problem of calculating the union area of axis-aligned rectangles, where rectangles may overlap. The standard efficient solution is to use a sweep line (scanline) algorithm with a segment tree, and discretize the y-coordinates because the coordinate range is huge but the number of rectangles is small.

**Solution outline:**
1. For each rectangle, create two events: one for the left edge (entering), one for the right edge (leaving).
2. Collect all y1 and y2, sort and deduplicate to discretize y-coordinates.
3. For each event, update the segment tree to reflect the current coverage on the y-axis.
4. As we process events in order of x, for each x-interval, multiply the width (delta x) by the total covered y-length (from the segment tree) to get the area for that slice.
5. Accumulate the area, taking modulo 1e9+7.

**C++ code:**
```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
const int MOD = 1e9+7;

struct Event {
    ll x;
    int y1, y2;
    int type; // +1 for entering, -1 for leaving
    Event(ll _x, int _y1, int _y2, int _type): x(_x), y1(_y1), y2(_y2), type(_type) {}
    bool operator<(const Event& e) const { return x < e.x; }
};

struct SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len;
    vector<ll> ys;
    SegmentTree(const vector<ll>& y): ys(y) {
        n = ys.size() - 1;
        cnt.assign(4*n, 0);
        len.assign(4*n, 0);
    }
    void update(int idx, int l, int r, int ql, int qr, int val) {
        if (qr <= l || r <= ql) return;
        if (ql <= l && r <= qr) {
            cnt[idx] += val;
        } else {
            int m = (l + r) / 2;
            update(idx*2, l, m, ql, qr, val);
            update(idx*2+1, m, r, ql, qr, val);
        }
        if (cnt[idx] > 0) len[idx] = ys[r] - ys[l];
        else if (r - l == 1) len[idx] = 0;
        else len[idx] = len[idx*2] + len[idx*2+1];
    }
};

int main() {
