        for (List<Integer> way : allWays) {
            System.out.println(way);
        }
    }

    // 回溯法
    private static void findWays(int n, List<Integer> path, List<List<Integer>> allWays) {
        int sum = path.stream().mapToInt(Integer::intValue).sum();
        if (sum == n) {
            allWays.add(new ArrayList<>(path));
            return;
        }
        if (sum > n) return;

        // 走一步
        path.add(1);
        findWays(n, path, allWays);
        path.remove(path.size() - 1);

        // 走两步
        path.add(2);
        findWays(n, path, allWays);
        path.remove(path.size() - 1);
    }
}
